import subprocess,json,sys
prefix="repos/G-ACE-inc/server-core/"
def api(method,path,data=None):
 args=["gh","api","-X",method,prefix+path]
 if data is not None:args+=["--input","-"]
 p=subprocess.run(args,input=json.dumps(data) if data is not None else None,capture_output=True,text=True,timeout=35)
 if p.returncode:raise RuntimeError("GITHUB_"+path.split("/")[0]+"_DENIED_"+str(p.returncode))
 return json.loads(p.stdout)
try:
 p=api("GET","pulls/300")
 if p["head"]["sha"]!="641e3391fe01cc2f5451e5070091cf3fcefc72f8" or not p["draft"] or p["state"]!="open":raise RuntimeError("PR_HEAD_OR_STATE_CHANGED")
 files=api("GET","pulls/300/files?per_page=100")
 if sorted(x["filename"] for x in files)!=["scripts/chat_cu_continuation.py","scripts/chat_cu_continuation_test.py"]:raise RuntimeError("PR_FILES_CHANGED")
 merged=api("POST","merges",{"base":"main","head":"agent-pool/cu40-failed-job-pagination-20261016","commit_message":"Agent Pool CU40: fix paginated run-job recovery while preserving Codex quota"})
 after=api("GET","pulls/300")
 if after.get("merged") is not True:raise RuntimeError("NOT_MERGED_AFTER_API")
 print("AGENT_POOL_PR300_MERGED="+json.dumps({"pr":300,"sha":merged.get("sha"),"merged":True,"ready_review_triggered":False}))
except Exception as e:
 print("AGENT_POOL_PR300_MERGE_FAILED="+str(e)[:120])
 sys.exit(1)
PY
